import pandas as pd,gzip,tarfile,re
h=pd.read_csv('studies/data/reference/hgnc_complete_set_2026-09-26.txt',sep='\t',low_memory=False,dtype=str)
ent=dict(zip(h.entrez_id.dropna(),h.hgnc_id[h.entrez_id.notna()]))
ens=dict(zip(h.ensembl_gene_id.dropna(),h.hgnc_id[h.ensembl_gene_id.notna()]))
sym=dict(zip(h.symbol,h.hgnc_id))
prev={};ali={}
for col,dd in [('prev_symbol',prev),('alias_symbol',ali)]:
    for s,i in zip(h[col],h.hgnc_id):
        if isinstance(s,str):
            for x in s.split('|'): dd.setdefault(x,set()).add(i)
def bysym(s):
    if s in sym: return sym[s]
    if s in prev and len(prev[s])==1: return next(iter(prev[s]))
    if s in ali and len(ali[s])==1: return next(iter(ali[s]))
def annot(f):
    d=pd.read_csv(gzip.open('studies/data/raw/'+f,'rt',errors='ignore'),sep='\t',skiprows=27,dtype=str)
    d=d[d.ID.notna() & ~d.ID.str.startswith('!')]
    S=set();Ssym=set()
    for g,s in zip(d['Gene ID'],d['Gene symbol']):
        if not isinstance(g,str): continue
        gs=g.split('///'); ss=s.split('///') if isinstance(s,str) else []
        if len(gs)!=1: continue  # single-gene probes only
        i=ent.get(gs[0]) or (bysym(ss[0]) if ss else None)
        if i:S.add(i)
    return S
